pub fn cmd_ca_init() -> anyhow::Result<()> {
    let ca_dir = dirs::home_dir().unwrap().join(".agentshield/ca");
    std::fs::create_dir_all(&ca_dir)?;
    let key_path = ca_dir.join("key.pem");
    let cert_path = ca_dir.join("cert.pem");
    if key_path.exists() {
        println!("CA exists. Overwrite? [y/N]"); // read confirmation
    }
    let key_pair = rcgen::KeyPair::generate(&rcgen::PKCS_ECDSA_P256_SHA256)?;
    let mut params = rcgen::CertificateParams::new(vec![]);
    params.is_ca = rcgen::IsCa::Ca(rcgen::BasicConstraints::Unconstrained);
    params.distinguished_name.push(rcgen::DnType::CommonName, "AgentShield CA");
    params.distinguished_name.push(rcgen::DnType::OrganizationName, "AgentShield");
    params.not_after = time::OffsetDateTime::now_utc() + time::Duration::days(3650);
    let cert = params.self_signed(&key_pair)?;
    std::fs::write(&key_path, key_pair.serialize_pem())?;
    std::fs::write(&cert_path, cert.pem())?;
    println!("CA generated: {} {}", key_path.display(), cert_path.display());
    Ok(())
}
```

